    /**
     * Fetches events from API and updates the Of The Week panel
     */
    private void fetchAndUpdateEvents() {
        dataManager.getEventsAsync().thenAccept(response -> {
            SwingUtilities.invokeLater(() -> {
                updateOfTheWeekPanel(response);
            });
        });
    }

