    /**
     * Updates the missing item count label
     */
    private void updateMissingItemCount(int count) {
        if (count > 0) {
            missingItemCountLabel.setText(count + " item" + (count != 1 ? "s" : ""));
        } else {
            missingItemCountLabel.setText("");
