package gg.embargo.bingo;

import lombok.Builder;
import lombok.Data;

import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

@Data
@Builder
public class BingoTile {
    private final int id;
    private final int bingoBoardId;
    private final int position;
    private final String title;
    private final String description;
    private final String imageUrl;
    private final String wikiKey;
    @Builder.Default
    private final int points = 1;
    @Builder.Default
    private final BingoTileType tileType = BingoTileType.SINGLE;
    @Builder.Default
    private final int requiredCount = 1;
    @Builder.Default
    private final List<BingoItemRequirement> itemRequirements = Collections.emptyList();
    @Builder.Default
    private final List<BingoItemGroup> itemGroups = Collections.emptyList();

    public Set<Integer> getValidItemIds() {
        Set<Integer> ids = itemRequirements.stream()
                .map(BingoItemRequirement::getItemId)
                .collect(Collectors.toSet());

        for (BingoItemGroup group : itemGroups) {
            ids.addAll(group.getItemIds());
        }

        return ids;
    }

    public boolean acceptsItem(int itemId) {
        if (itemRequirements.stream().anyMatch(req -> req.getItemId() == itemId)) {
            return true;
        }

        for (BingoItemGroup group : itemGroups) {
            if (group.containsItem(itemId)) {
                return true;
            }
        }

        return false;
    }

    public boolean isAutoTracked() {
        return tileType != BingoTileType.XP && tileType != BingoTileType.KC;
    }

    public int getRow(int boardSize) {
        return position / boardSize;
    }

    public int getColumn(int boardSize) {
        return position % boardSize;
    }
}

package gg.embargo.bingo;

import lombok.Builder;
import lombok.Data;

import java.awt.*;
import java.util.Collections;
import java.util.List;

@Data
@Builder
public class BingoTeam {
    private final int id;
    private final int bingoBoardId;
    private final String name;
    private final String colorHex;
    @Builder.Default
    private final int totalPoints = 0;
    @Builder.Default
    private final int completedTiles = 0;
    @Builder.Default
    private final int partialTiles = 0;
    @Builder.Default
    private final List<String> members = Collections.emptyList();

    public Color getColor() {
        if (colorHex == null || colorHex.isEmpty()) {
            return Color.GRAY;
        }
        try {
            return Color.decode(colorHex);
        } catch (NumberFormatException e) {
            return Color.GRAY;
        }
    }

    public boolean hasMember(String rsn) {
        if (rsn == null || members == null) {
            return false;
        }
        return members.stream()
                .anyMatch(member -> member.equalsIgnoreCase(rsn));
    }
}

package gg.embargo.bingo;

import lombok.Builder;
import lombok.Data;

import java.time.Duration;
import java.time.Instant;
import java.time.ZonedDateTime;
import java.util.*;
import java.util.stream.Collectors;

@Data
@Builder
public class BingoState {
    private final int id;
    private final String name;
    private final String description;
    @Builder.Default
    private final int size = 5;
    private final Instant startDate;
    private final Instant endDate;
    private final String status;
    private final String codeword;
    @Builder.Default
    private final Map<Integer, BingoTile> tiles = Collections.emptyMap();
    private final BingoTeam userTeam;
    @Builder.Default
    private final Map<Integer, BingoTeamTileProgress> teamProgress = Collections.emptyMap();
    @Builder.Default
    private final Map<Integer, Set<Integer>> itemIdToTileIds = Collections.emptyMap();

    public boolean isEnrolled() {
        return userTeam != null;
    }

    public boolean isActive() {
        return "active".equalsIgnoreCase(status);
    }

    public boolean hasEnded() {
        return endDate != null && Instant.now().isAfter(endDate);
    }

    public boolean hasStarted() {
        return startDate == null || Instant.now().isAfter(startDate);
    }

    public Duration getTimeRemaining() {
        if (endDate == null) {
            return Duration.ofDays(365);
        }
        Instant now = Instant.now();
        if (now.isAfter(endDate)) {
            return Duration.ZERO;
        }
        return Duration.between(now, endDate);
    }

    public BingoTile getTile(int tileId) {
        return tiles.get(tileId);
    }

    public BingoTeamTileProgress getProgress(int tileId) {
        return teamProgress.get(tileId);
    }

    public Set<Integer> getTileIdsForItem(int itemId) {
        return itemIdToTileIds.getOrDefault(itemId, Collections.emptySet());
    }

    public boolean hasItemRequirement(int itemId) {
        return itemIdToTileIds.containsKey(itemId);
    }

    public List<BingoTile> getTilesByPosition() {
        return tiles.values().stream()
                .sorted(Comparator.comparingInt(BingoTile::getPosition))
                .collect(Collectors.toList());
    }

    public int getCompletedTileCount() {
        return (int) teamProgress.values().stream()
                .filter(BingoTeamTileProgress::isCompleted)
                .count();
    }

    public List<BingoTile> getIncompleteTiles() {
        Set<Integer> completedTileIds = teamProgress.entrySet().stream()
                .filter(e -> e.getValue().isCompleted())
                .map(Map.Entry::getKey)
                .collect(Collectors.toSet());

        return tiles.values().stream()
                .filter(tile -> !completedTileIds.contains(tile.getId()))
                .collect(Collectors.toList());
    }

    public String getFormattedTimeRemaining() {
        Duration remaining = getTimeRemaining();
        long totalMinutes = remaining.toMinutes();

        if (totalMinutes <= 0) {
            return "Ended";
        }

        long days = remaining.toDays();
        long hours = remaining.toHours() % 24;
        long minutes = totalMinutes % 60;

        if (days > 0) {
            return String.format("%dd %dh", days, hours);
        } else if (hours > 0) {
            return String.format("%dh %dm", hours, minutes);
        } else {
            return String.format("%d min", minutes);
        }
    }

    public static Map<Integer, Set<Integer>> buildItemLookup(Map<Integer, BingoTile> tiles) {
        Map<Integer, Set<Integer>> lookup = new HashMap<>();
        if (tiles != null) {
            for (BingoTile tile : tiles.values()) {
                for (int itemId : tile.getValidItemIds()) {
                    lookup.computeIfAbsent(itemId, k -> new HashSet<>()).add(tile.getId());
                }
            }
        }
        return lookup;
    }
}

package gg.embargo.commands;

import gg.embargo.DataManager;
import gg.embargo.EmbargoConfig;
import gg.embargo.commands.embargo.Rank;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatCommandManager;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.eventbus.EventBus;

import javax.inject.Inject;
import java.awt.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

@Slf4j
public class CommandManager {
    @Inject
    private ClientThread clientThread;

    @Inject
    private EmbargoConfig config;

    @Inject
    private Client client;

    @Inject
    private DataManager dataManager;

    @Inject
    private ChatCommandManager chatCommandManager;

    private final EventBus eventBus;

    private static final String EMBARGO_COMMAND = "!embargo";

    @Inject
    public CommandManager(Client client, ClientThread clientThread, EventBus eventBus, EmbargoConfig config) {
        this.client = client;
        this.clientThread = clientThread;
        this.eventBus = eventBus;
        this.config = config;
    }

    public void startUp() {
        eventBus.register(this);
        chatCommandManager.registerCommandAsync(EMBARGO_COMMAND, this::processEmbargoLookupChatCommand);
    }

    public void shutDown() {
        eventBus.unregister(this);
        chatCommandManager.unregisterCommand(EMBARGO_COMMAND);
    }

    // Helper method to update chat message safely on the client thread
    private void updateChatMessage(ChatMessage chatMessage, String message) {
        clientThread.invokeLater(() -> {
            chatMessage.getMessageNode().setRuneLiteFormatMessage(message);
            client.refreshChat();
        });
    }

    public void processEmbargoLookupChatCommand(ChatMessage chatMessage, String message) {
        int firstWhitespace = message.indexOf(' ');
        String memberName = (firstWhitespace != -1 && firstWhitespace + 1 < message.length())
                ? message.substring(firstWhitespace + 1)
                : chatMessage.getName().replaceAll("<[^>]*>", "");

        String loadingMessage = new ChatMessageBuilder()
                .append(ChatColorType.HIGHLIGHT)
                .append("Looking up Embargo member...")
                .build();

        updateChatMessage(chatMessage, loadingMessage);

        String finalMemberName = memberName.replace('\u00A0', ' ').trim();
        dataManager.getProfileAsync(finalMemberName, true).thenAccept(embargoProfileData -> {
            // Null checks for safety
            if (embargoProfileData == null
                    || embargoProfileData.get("accountPoints") == null
                    || embargoProfileData.getAsJsonPrimitive("communityPoints") == null
                    || embargoProfileData.getAsJsonPrimitive("currentRank") == null) {
                String memberNotFound = new ChatMessageBuilder()
                        .append(ChatColorType.HIGHLIGHT)
                        .append("Error retrieving data for member: " + finalMemberName)
                        .build();
                updateChatMessage(chatMessage, memberNotFound);
                return;
            }

            String currentRankName = embargoProfileData.getAsJsonPrimitive("currentRank").getAsString();
            String leaderboardPosition = embargoProfileData.getAsJsonObject("leaderboardRank").get("currentPosition")
                    + "/"
                    + embargoProfileData.getAsJsonObject("leaderboardRank").get("totalPositions");
            Color rankColor = Rank.getColorByName(currentRankName);
            Color labelColor = config.chatCommandOutputColor();

            String outputMessage = new ChatMessageBuilder()
                    .append(labelColor, "Member: ")
                    .append(finalMemberName)
                    .append(labelColor, " Rank: ")
                    .append(rankColor, currentRankName)
                    .append(labelColor, " Account Points: ")
                    .append(ChatColorType.HIGHLIGHT)
                    .append(String.valueOf(embargoProfileData.get("accountPoints")))
                    .append(labelColor, " Community Points: ")
                    .append(ChatColorType.HIGHLIGHT)
                    .append(String.valueOf(embargoProfileData.getAsJsonPrimitive("communityPoints")))
                    .append(labelColor, " Leaderboard Rank: ")
                    .append(ChatColorType.HIGHLIGHT)
                    .append(leaderboardPosition)
                    .build();

            updateChatMessage(chatMessage, outputMessage);
        }).exceptionally(ex -> {
            String memberNotFound = new ChatMessageBuilder()
                    .append(ChatColorType.HIGHLIGHT)
                    .append("Member " + finalMemberName + " not found.")
                    .build();
            updateChatMessage(chatMessage, memberNotFound);
            return null;
        });
    }

}

